// The browser tab is the only place several open plans can be told apart,
// so a plan puts its own name there.
export const DEFAULT_TITLE = '交大課程助理'

export const setPageTitle = (text) => {
    document.title = text ? `${text} - ${DEFAULT_TITLE}` : DEFAULT_TITLE
}

export const resetPageTitle = () => {
    document.title = DEFAULT_TITLE
}
